import sys
import heapq

def dijkstra(rooms, events):
    n = len(events)
    time = 0
    queued = set(events[:n])
    cost = [float('inf')] * (n + 1)
    cost[n] = 0

    for event_id in range(n - 1, -1, -1):
        event = events[event_id]
        if event[0] == "-":
            # Cancel an event
            i = queued.pop()
            cost[i] = float('inf')
            for event_id in range(n):
                for time, ekt in rooms[event_id]:
                    if ekt == i:
                        cost[event_id] = min(cost[event_id], time + i + 3)
        elif event[0] == "+":
            # Queue a new event
            queued.add(event_id)
            for idx in reversed(range(n, 0, -1)):
                if idx <= event_id:
                    i = queued.pop()
                    cost[idx] = min(cost[idx], time + 3)
                else:
                    rooms[idx][1] += 1
    return cost

if __name__ == "__main__":
