import math

def is_perfect_square(x):
    s = int(math.sqrt(x))
    return s * s == x

def prime_factors(n):
    i = 2
    factors = {}
    while i * i <= n:
        while (n % i) == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def make_good(s, p):
    for i in range(len(s)):
        total = 1
        for j, prime in p.items():
            total *= prime ** (s.count(prime) // prime)
        s[i:i+prime * prime * total] = [prime] * prime * total
    return s

