MOD = 998244353

def combine(n: int, r: int) -> int:
    return factorial(n) * pow(factorial(r) * factorial(n-r), MOD-2, MOD)

def partition_tree_leaves(n: int, parent: List[int]) -> int:
    leaves = []
    for i in range(1, n+1):
        if parent[parent[i]] != i:
            continue
        leaves.append(i)
    dp = [1] + [0] * (len(leaves)-1)
    for leaf in reversed(leaves):
        for child in parent[leaf]:
            dp[child] += max(0, dp[leaf] - 1)
        dp[leaf] -= combine(len(leaves) - 1, len(leaves) - 1 - len(dp))
        dp[leaf] %= MOD
    return combine(len(leaves), len(dp)) // 6

