                index = int(event.split()[1]) - 1
                del event_queue[index]
            elif event.startswith('?'):
                if not event_queue:
                    print(0)
                else:
                    wait_time = 0
                    for _, end_time in reversed(event_queue):
                        if end_time <= int(event.split()[1]):
                            wait_time = int(event.split()[1]) - (end_time if wait_time > end_time else wait_time)
                            break
                    print(wait_time)
            else:
                raise ValueError(f"Unknown event: {event}")
