import sys
import math
from typing import List

def is_square(n: int) -> bool:
    return int(math.sqrt(n))**2 == n

def f(arr: List[int]) -> int:
    cache = {}

    def dp(i: int, last_p: int, last_fn: int) -> int:
        if i == len(arr):
            return 0
        if (i, last_p, last_fn) in cache:
            return cache[(i, last_p, last_fn)]

        val = arr[i]
        res = float('inf')
        prime = find_prime(val)
        if prime:
            primes = find_prime_tree(prime)
            for j, c in enumerate(pairs(primes, prime, last_p, last_fn)):
                fn = (c - 1) * j
                if is_square((c - 1) * fn):
                    res = min(res, dp(i+1, c, fn))
        cache[(i, last_p, last_fn)] = res
        return res

    return dp(0, -1, 0)

def find_prime(n: int) -> int:
    primes = [2]

    for i in range(3, n//2 + 1, 2):
        primes += [i if is_prime(i) else primes[-1]] if all(i % p != 0 for p in primes) else []

    return primes[-1]

def is_prime(n: int) -> bool:
    if n <= 1 or n % 2 == 0:
        return n == 2
    if n.bit_length() <= 2048:
        return all(not (bin(n)[-2] == '0' or not (n & (n - 1))) for n in range(3, n + 1, 2))
    else:
        return all(not (n % p == 0 for p in range(3, int(n**0.5) + 1, 2)))

def pairs(primes: List[int], p: int, a: int, b: int) -> List[int]:
    return [a - p, a + p, b - p, b + p]

def find_prime_tree(prime: int) -> List[int]:
    primes = [prime]
    cp = prime

    for i in range(2, int(math.sqrt(cp)) if cp.bit_length() <= 2048 else 100):
        cp = solve(coprime(cp, i), i)
        if cp != 0:
            primes.append(cp)

    return primes

def solve(x: int, p: int) -> int:
    if not x % p:
        return x
    return x - (x // (p * (x // p + 1)) * p)

def coprime(a: int, b: int) -> bool:
    return bin(a)[-1] == '0' and bin(b)[-1] == '1' or bin(a)[-1] == '1' and bin(b)[-1] == '0'

