                if val < lower_bound[i]:
                    stack.queue.append(i)
                    min_stack.popleft()
                    min_stack.append(i)
                elif val > lower_bound[i]:
                    stack.popleft()
                    if len(stack) == l:
                        stack.append(i)
                    elif i >= l or len(min_stack) < len(stack):
                        stack.append(i)
        elif i > r:
            if stack and a[stack[-1]] == a[i]:
                if result <= k:
                    result = 1
                    return result
                else:
                    break
            stack.popleft()
            if stack and i >= stack[-1] + 1:
                if i - stack[-1] <= r - i:
                    min_stack.popleft()
                    stack.append(i)
                elif len(min_stack) == l:
                    min_stack.append(i)
                else:
                    stack.append(i)

    return result

