from collections import defaultdict
from heapq import heappush, heappop
from typing import List

def select_segments(a: List[int], s: List[List[int]], m: int, k: int) -> int:
    interval_to_segments = defaultdict(set)
    for segment in s:
        if segment[0] == 1:
            interval_to_segments[0].add(segment[1]-1)

    for i, j in s:
        interval_to_segments[j-i+1].add(i-1)

    multiset = [defaultdict(int)] * (max(a) + 1)

    for interval, num in interval_to_segments.items():
        left, right = min(num), max(num)
        for k in range(left, right+1):
            multiset[k].update([interval])

    d = [-v.item() for v in multiset]
    heapq.heapify(d)
    final = []
    res = -1
    while d and len(final) < m:
        res = k - final[-1][0]
        if res > 0:
            final = [final[1:]]
            res = -1 
        dest, src, next_dest = None, final[0][1], 0
        for i in range(len(final)):
            v = final[i]
            if v[1] - v[0] <= 2:
                source, next_source = final[i-1], final[i]
                if source[1] - source[0] <= 1:
                    dest, next_dest = max(next_dest, (v[1], (source[0]+source[1])/2))
                elif next_source[1] - next_source[0] <= 1:
                    dest, next_dest = max(dest, (v[1], (source[1]+v[1])/2))
                else:
                    dest, next_dest = max(next_dest, (v[1], (source[0]+source[1]+v[1]) / 3))
            else:
                dest = max(dest, (v[1], (v[0]+v[1]) / 2))
                next_dest = max(next_dest, (d[source[1]], (source[0]+source[1]) / 2))

        for source, dest in [(dest, next_dest)] + final[::-1]:
            src += multiset[source][dest.key() - num(source)][-1] * source.size + multiset[dest.key()][dest[1]-num(dest)][-1]
            heappush(final, (src, dest))

    return -1 if len(final) < m else next(dest.src) - multiset[dest.key()][dest.key()][dest.dst-dest.src][0]


