import sys

class SegmentTree:
    def __init__(self, arr):
        self.root = self.build(arr, 0, len(arr)-1)

    def build(self, arr, start, end, delta=0):
        node = {}
        if start == end:
            node['val'] = arr[start]
        else:
            mid = (start + end) // 2
            left_node = self.build(arr, start, mid, delta)
            right_node = self.build(arr, mid + 1, end, delta)
            node['val'], node['sum'] = self.merge(left_node, right_node, start, mid, mid + 1, end)
            node['cnt'] = left_node['cnt'] + right_node['cnt'] + node['sum'] + delta
        return node

    def merge(self, left_node, right_node, left, mid, right, right_ind):
        node = {}
        node['val'] = left_node['val'] + right_node['val']
        node['sum'] = left_node['sum'] + right_node['sum']
        node['cnt'] = left_node['cnt'] + right_node['cnt'] + left + right
        return (node['val'], node['sum'], node['cnt'])

    def query(self, l, r, start, end):
        if r < start or l > end:
            return []
        elif l <= start and r >= end:
            return [self.root]
        mid = (start + end) // 2
        left_nodes = self.query(l, r, start, mid)
        right_nodes = self.query(l, r, mid + 1, end)
        left_sum = left_nodes[-1]['sum'] + left_nodes[-1]['cnt']
        right_sum = mid - start + right_nodes[-1]['cnt'] + right_nodes[-1]['sum']
        best_sum = left_sum + right_sum - mid - 1 + left_nodes[-1]['val'] + right_nodes[-1]['val']
        left = left_sum + self.cmp(left_nodes, best_sum)
        right = right_sum + self.cmp(right_nodes, best_sum)
        best_sum = best_sum + mid - start + left + right
        node = {
            'val': best_sum + left_nodes[-1]['val'],
            'sum': [left_sum, right_sum],
            'cnt': left_nodes[-1]['cnt'] + right_nodes[-1]['cnt'] + mid + 1
        }
        return [node]

    def cmp(self, node, best):
        if node["sum"][0] > node["sum"][1]:
            best = max(best, node["val"])
            self.cmp_best(node["sum"][1], node)
            return best
        else:
            self.cmp_best(node["sum"][0], [])
            return best

    def cmp_best(self, best_val, nodes):
        if len(nodes):
            node = max(nodes)
            if best_val < node["sum"][1]:
                best_val = node["val"] + node["sum"][1]
                self.cmp_best(best_val, node)
                return best_val
            else:
                self.cmp_best(best_val, nodes)
                return best_val

class TreeNode:
