    def product_of_combinations(m, k):
        if k > m:
            return 0
        return (1 + 1) // (k + 1) * (m - (m - k) % k + 1)

    # Helper function to recursively count partitions
    def count_partitions(current, parent, count):
        if parent not in current:
            # Check if the current partition is valid
            pieces = [0] * len(parents)
            pieces[parent] = count
            pieces = tuple(pieces)
            if pieces not in visited:
                visited[pieces] = 1
                combinatorics = product_of_combinations(len(parent), count)
                return combinatorics
        for child in tree[parent]:
            visited[parent] = None
            combs = count_partitions(current.copy(), child, count - 1)
            visited[parent] = pieces[parent]
            if pieces[parent] is not None:
                continue
            current[child] = count
            current = current | {child}
            visited[child] = pieces[child]
            tmp = 0
            pieces[child] = count
            for i in range(count + 1):
                if pieces[parent] // (count - i) > count - i:
                    continue
                tmp += combinatorics * count_partitions(current.copy(), child, pieces[parent] // (count - i))
                break
            current[child] = 0
            current = current - {child}
        return tmp + product_of_combinations(len(parent), count)

