import sys

def tournament(players, sorted_players):
    matches = [[p, sorted_players[p-1]] for p in range(1, len(sorted_players)) if sorted_players[p-1] > players[p-1]]

    result = []
    while players and sorted_players:
        if matches:
            player, loser = matches.pop(0)
            if player > loser:
                result.append(player)
                players.remove(player)
                sorted_players.remove(loser)
            else:
                result.append(loser)
                players.remove(loser)
                sorted_players.remove(player)
        else:
            break

    if players:
        result.append(min(players))
    return ''.join(map(str, result))

