def minMovesForRiddle(scales: List[List[int]], weights: List[int]) -> int:
    n = len(scales)
    left_shifts = [0] * n
    right_shifts = [0] * n

    # Set the minimum possible moves needed to shift weights horizontally.
    for i, (a, lhi, rhi) in enumerate(scales):
        max_right = weights[-1] - a
        min_left = weights[0] - a
        if lhi <= max_right and (max_right - lhi) % 2 == ((rhi - lhi) % 2):
            left_shifts[i] = 0
        else:
            min_left -= a
            max_right -= a

        if a >= 1:
            left_shifts[i] += min(lhi + a - max_right, 1)

        if a <= -1:
            left_shifts[i] += abs(a - (max_right - a))

        if lhi <= 0:
            left_shifts[i] += weights[0] - a + max_right
            min_left -= a
        else:
            min_left -= a

        if rhi >= weights[-1]:
            right_shifts[i] = 0
        else:
            max_left = weights[0] - a
            min_right = weights[-1] - a
            if (max_right + lhi) % 2 == ((max_right + min_right) % 2):
                right_shifts[i] = 0
            else:
                max_left -= a
                min_right -= a

            if max_right + lhi < 0:
                right_shifts[i] += max(0, abs(a - (max_right - a)) + weights[0] - a + max_right)
            else:
                max_left -= a
                min_right -= a
                right_shifts[i] += weights[-1] - a + abs(max_right + lhi - a)

            if max_left <= 0:
                right_shifts[i] -= max(abs(lhi - a), a - (max_right + lhi))
            else:
                right_shifts[i] -= weights[0] - a + abs(max_right + lhi - a)

            if a >= 1:
                right_shifts[i] -= weights[-1] - a + max(a - (max_right + lhi), 0)

            if a <= -1:
                right_shifts[i] += max(0, abs(a - (a - 1 + max_right + lhi)))

    rewards = [[int(j <= x <= i or x <= j <= i) for i, j in enumerate(weights)] for j in left_shifts]

    dp = [[0, n] for _ in range(len(weights))]
    num_instances = len(weights)
    rewards.reverse()

    for window_start in range(n):
        for reward, num_instances in reversed(rewards):
            if window_start == 0:
                dp[num_instances - 1][0], dp[num_instances - 1][1] = reward, num_instances
            else:
                dp[num_instances - 1][0], dp[num_instances - 1][1] = reward + max(0, dp[num_instances - 1][0] - reward),
                dp[num_instances - 1][1] = min(dp[num_instances - 1][1] + reward, n + weights[-num_instances], cuts - (weights[-num_instances * window_start // reward] - cuts))
