                    dp[num_instances - 1][1] = min(dp[num_instances - 1][1] + reward + 1 - reward + cuts, n + weights[num_instances - 1], cuts - (weights[num_instances - 1] - cuts))

    return n + dp[num_instances - 1][1] + 1

