from collections import defaultdict
from heapq import heapify, heappop, heappush

def min_moves(nums):
    graph = defaultdict(list)
    edge_weights = defaultdict(list)
    last = sorted(zip(nums, [0, 1]), reverse=True)

    for node, (weight, length) in enumerate(last, start=1):
        for i in range(length):
            other = node + i
            if node % 2:
                other += length
            if other >= len(nums):
                other -= len(nums)
            if nums[other] - weight < 0 or nums[node] - weight < 0:
                continue

            edge_weights[node].append(weight)
            graph[node].append(other)

            edge_weights[other].append(-weight)
            graph[other].append(node)

    # Set of all edges with weight 0
    black_list = set()
    for node, weights in graph.items():
        if 0 in weights:
            black_list.add(node)

    heads = list(black_list)
    tails = []

    mindist = {tail : float('inf') for tail in tails}
    distances = {head : 0 for head in heads}
    mindist[heads[-1]] = 0

    for head in heads:
        mindist[head] = 0

    while heads:
        head = heads.pop()

        if mindist[head] == float('inf'):
            return float('inf')

        for tail in tails:
            last = last.pop(0)
            new = min(last[1] - weights[head] + weights[tail], last[0] - weights[tail])

            if new < mindist[tail] and new != float('inf'):
                mindist[tail] = new

        for tail in tails:
            newdist = distances[head] + mindist[tail]
            if newdist < mindist[tail]:
                tails.append(tail)
                mindist[tail] = newdist

    return mindist[5]

